ngular/core';\nimport { IonicPageModule } from 'ionic-angular';\nimport { AddbraceletPage } from './addbracelet';\n\n@NgModule({\n  declarations: [\n    AddbraceletPage,\n  ],\n  imports: [\n    IonicPageModule.forChild(AddbraceletPage),\n  ],\n})\nexport class AddbraceletPageModule {}\n\n\n\n// WEBPACK FOOTER //\n// ./src/pages/addbracelet/addbracelet.module.ts","import { Component } from '@angular/core';\nimport { IonicPage, NavController, NavParams } from 'ionic-angular';\nimport { FormBuilder, FormGroup, Validators } from '@angular/forms';\n\n\nimport { Bracelet } from './../../models/bracelet.model';\nimport { BraceletListService } from '../../providers/database/bracelet-list.service';\n\n@IonicPage()\n@Component({\n  selector: 'page-addbracelet',\n  templateUrl: 'addbracelet.html',\n})\nexport class AddbraceletPage {\n\n    ctrls_add: FormGroup;\n\n    bracelet : Bracelet = {\n        code: \"\",\n        client_secret: \"\",\n        serial: \"\"\n    };\n\n    constructor(\n        public navCtrl: NavController,\n        public navParams: NavParams,\n        private braceletListService: BraceletListService,\n        public formBuilder: FormBuilder\n    ) {\n\n        this.ctrls_add = this.formBuilder.group({\n            code: ['', Validators.compose([Validators.maxLength(10), Validators.pattern('[a-zA-Z0-9 ]*'), Validators.required])],\n            client_secret: ['', Validators.compose([Validators.maxLength(50), Validators.required])],\n            serial: ['', Validators.compose([Validators.maxLength(30), Validators.pattern('[a-zA-Z0-9 ]*'), Validators.required])],\n        });\n\n    }\n\n    addBracelet() {\n\n        if(this.ctrls_add.valid){\n            this.bracelet.code = this.ctrls_add.controls.code.value;\n            this.bracelet.client_secret = this.ctrls_add.controls.client_secret.value;\n            this.bracelet.serial = this.ctrls_add.controls.serial.value;\n\n            this.braceletListService.addBracelet(this.bracelet).then(ref => {\n                this.navCtrl.setRoot('AdminbraceletPage');\n            });\n        }\n        \n    }\n\n    toListBracelet() {\n    \t\n    \tthis.navCtrl.setRoot('AdminbraceletPage');\n    \t\n    }\n\n}\n\n\n\n// WEBPACK FOOTER //\n// ./src/pages/addbracelet/addbracelet.ts"],"sourceRoot":""}
